DICTIONARIES = {
    'blockMeshDict': '/*--------------------------------*- C++ -*----------------------------------*\\\n| =========                 |                                                 |\n| \\\\      /  F ield         | OpenFOAM: The Open Source CFD Toolbox           |\n|  \\\\    /   O peration     | Website:  www.openfoam.org                      |\n|   \\\\  /    A nd           | Version:  12                                    |\n|    \\\\/     M anipulation  |                                                 |\n\\*---------------------------------------------------------------------------*/\nFoamFile\n{\n    version     2.0;\n    format      ascii;\n    class       dictionary;\n    object      blockMeshDict;\n}\n// * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * //\n\nconvertToMeters 1;\n\nvertices\n(\n    (-0.01 -0.01 0.00)\t\n    (0.16 -0.01 0.00)\n    (0.16 0.16 0.00)\n    (-0.01 0.16 0.00)\n    (-0.01 -0.01 0.003)\n    (0.16 -0.01 0.003)\t\n    (0.16 0.16 0.003)\n    (-0.01 0.16 0.003)\n);\n\nblocks\n(\n   hex (0 1 2 3 4 5 6 7) (240 240 5) \t        simpleGrading (1 1 1)\t\t\t\t//block 1\n\n);\n\nedges\n(\n);\n\npatches\n(  \n  patch maxY\n(\n  (3 7 6 2)\n)\n  patch minX\n(\n  (0 4 7 3)\n)\n  patch maxX\n(\n  (2 6 5 1)\n)\n  patch minY\n(\n  (1 5 4 0)\n)\n  patch maxZ\n(\n  (0 3 2 1)\n)\n  patch minZ\n(\n  (4 5 6 7)\n)\n\n);\n\nmergePatchPairs\n(\n);\n\n// ************************************************************************* //\n',
    'controlDict': '/*--------------------------------*- C++ -*----------------------------------*\\\n| =========                 |                                                 |\n| \\\\      /  F ield         | OpenFOAM: The Open Source CFD Toolbox           |\n|  \\\\    /   O peration     | Website:  www.openfoam.org                      |\n|   \\\\  /    A nd           | Version:  12                                    |\n|    \\\\/     M anipulation  |                                                 |\n\\*---------------------------------------------------------------------------*/\nFoamFile\n{\n    version     2.0;\n    format      ascii;\n    class       dictionary;\n    object      controlDict;\n}\n// * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * //\n\napplication     simpleFoam;\n\nstartFrom       startTime; \n\nstartTime       0;\n\nstopAt          endTime;\n\nendTime         5000;\n\ndeltaT          1;\n\nwriteControl    adjustableRunTime;\n\nwriteInterval   1000;\n\npurgeWrite      0;\n\n\nwriteFormat     binary;\n\nwritePrecision  10;\n\nwriteCompression uncompressed;\n\ntimeFormat      general;\n\ntimePrecision   6;\n\nrunTimeModifiable true;\n\nadjustTimeStep  yes;\n\nmaxCo           0.2;\n\n\n// ************************************************************************* //\n',
    'createPatchDict': '/*--------------------------------*- C++ -*----------------------------------*\\\n| =========                 |                                                 |\n| \\\\      /  F ield         | OpenFOAM: The Open Source CFD Toolbox           |\n|  \\\\    /   O peration     | Website:  www.openfoam.org                      |\n|   \\\\  /    A nd           | Version:  12                                    |\n|    \\\\/     M anipulation  |                                                 |\n\\*---------------------------------------------------------------------------*/\nFoamFile\n{\n    version     2.0;\n    format      ascii;\n    class       dictionary;\n    object      createPatchDict;\n}\n// * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * //\n\n// Do a synchronisation of coupled points after creation of any patches.\n// Note: this does not work with points that are on multiple coupled patches\n//       with transformations (i.e. cyclics).\npointSync false;\n\n// Patches to create. An empty patch list just removes patches with zero\n// faces from $FOAM_CASE/constant/polyMesh/boundary.\npatches\n(\n);\n\n// ************************************************************************* //\n',
    'extrudeMeshDict': '/*--------------------------------*- C++ -*----------------------------------*\\\n| =========                 |                                                 |\n| \\\\      /  F ield         | OpenFOAM: The Open Source CFD Toolbox           |\n|  \\\\    /   O peration     | Website:  www.openfoam.org                      |\n|   \\\\  /    A nd           | Version:  12                                    |\n|    \\\\/     M anipulation  |                                                 |\n\\*---------------------------------------------------------------------------*/\nFoamFile\n{\n    version     2.0;\n    format      ascii;\n    class       dictionary;\n    object      extrudeMeshDict;\n}\n// * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * //\n\n// What to extrude:\n//      patch   : from patch of another case (\'sourceCase\')\n//      mesh    : as above but with original case included\n//      surface : from externally read surface\n\n//constructFrom mesh;\nconstructFrom patch;\n\n// If construct from patch/mesh:\nsourceCase ".";\nsourcePatches (back);\n\n// If construct from patch: patch to use for back (can be same as sourcePatch)\nexposedPatchName front;\n\n// Flip surface normals before usage. Valid only for extrude from surface or\n// patch.\nflipNormals false;\n\n//- Wedge extrusion. If nLayers is 1 assumes symmetry around plane.\nextrudeModel        wedge;\n\nnLayers             1;\n\nexpansionRatio      0.002; \n\nsectorCoeffs\n{\n    axisPt      (0 0 0);\n    axis        (0 1 0);\n    angle       5;  // For nLayers=1 assume symmetry so angle/2 on each side\n}\n\n// Do front and back need to be merged? Usually only makes sense for 360\n// degree wedges.\nmergeFaces false;   //true;\n\n// Merge small edges. Fraction of bounding box.\nmergeTol 1e-6;\n\n\n// * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * //\n',
    'fvSchemes': '/*--------------------------------*- C++ -*----------------------------------*\\\n| =========                 |                                                 |\n| \\\\      /  F ield         | OpenFOAM: The Open Source CFD Toolbox           |\n|  \\\\    /   O peration     | Website:  www.openfoam.org                      |\n|   \\\\  /    A nd           | Version:  12                                    |\n|    \\\\/     M anipulation  |                                                 |\n\\*---------------------------------------------------------------------------*/\nFoamFile\n{\n    version     2.0;\n    format      ascii;\n    class       dictionary;\n    location    "system";\n    object      fvSchemes;\n}\n// * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * //\n\nddtSchemes\n{\n    default         Euler;\n}\n\ngradSchemes\n{\n    default         Gauss linear;\n    grad(p)         Gauss linear;\n    grad(U)         Gauss linear;\n}\n\ndivSchemes\n{\n    default         none;\n    div(phi,U)      bounded Gauss linearUpwindV grad(U);\n    div(phi,k)      Gauss linear;\n    div(phi,omega)  Gauss linear;\n    div((nuEff*dev(T(grad(U))))) Gauss linear;\n}\n\nlaplacianSchemes\n{\n    default             Gauss linear corrected;\n}\n\ninterpolationSchemes\n{\n    default         linear;\n    interpolate(U)  linear;\n}\n\nsnGradSchemes\n{\n    default         corrected;\n}\n\nfluxRequired\n{\n    default         no;\n    p               ;\n}\n\n\n// ************************************************************************* //\n',
    'fvSolution': '/*--------------------------------*- C++ -*----------------------------------*\\\n| =========                 |                                                 |\n| \\\\      /  F ield         | OpenFOAM: The Open Source CFD Toolbox           |\n|  \\\\    /   O peration     | Website:  www.openfoam.org                      |\n|   \\\\  /    A nd           | Version:  12                                    |\n|    \\\\/     M anipulation  |                                                 |\n\\*---------------------------------------------------------------------------*/\nFoamFile\n{\n    version     2.0;\n    format      ascii;\n    class       dictionary;\n    object      fvSolution;\n}\n// * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * //\n\nsolvers\n{\n    p\n    {\n        solver           GAMG;\n        tolerance        1e-8;\n        relTol           0.01;\n        smoother         GaussSeidel;\n        nPreSweeps       0;\n        nPostSweeps      2;\n        cacheAgglomeration on;\n        agglomerator     faceAreaPair;\n        nCellsInCoarsestLevel 10;\n        mergeLevels      1;\n    }\n\n    U\n    {\n        solver           smoothSolver;\n        smoother         GaussSeidel;\n        tolerance        1e-8;\n        relTol           0.1;\n        nSweeps          1;\n    }\n\n    k\n    {\n        solver           smoothSolver;\n        smoother         GaussSeidel;\n        tolerance        1e-8;\n        relTol           0.1;\n        nSweeps          1;\n    }\n\n    omega\n    {\n        solver           smoothSolver;\n        smoother         GaussSeidel;\n        tolerance        1e-8;\n        relTol           0.1;\n        nSweeps          1;\n    }\n}\n\nSIMPLE\n{\n    nNonOrthogonalCorrectors 0;\n}\n\npotentialFlow\n{\n    nNonOrthogonalCorrectors 10;\n}\n\nrelaxationFactors\n{\n    fields\n    {\n        p               0.3;\n    }\n    equations\n    {\n        U               0.7;\n        k               0.7;\n        omega           0.7;\n    }\n}\n\ncache\n{\n    grad(U);\n}\n\n// ************************************************************************* //\n',
    'meshQualityDict': '/*--------------------------------*- C++ -*----------------------------------*\\\n| =========                 |                                                 |\n| \\\\      /  F ield         | OpenFOAM: The Open Source CFD Toolbox           |\n|  \\\\    /   O peration     | Website:  www.openfoam.org                      |\n|   \\\\  /    A nd           | Version:  12                                    |\n|    \\\\/     M anipulation  |                                                 |\n\\*---------------------------------------------------------------------------*/\nFoamFile\n{\n    version     2.0;\n    format      ascii;\n    class       dictionary;\n    object      meshQualityDict;\n}\n\n// * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * //\n\nmeshQualityControls\n{\n   \n    maxNonOrtho 65;\n    maxBoundarySkewness 20;\n    maxInternalSkewness 4;\n    maxConcave 80;\n    minFlatness 0.5;\n    minVol 1e-13;\n    minTetQuality 1e-9;\n    minArea -1;\n    minTwist 0.02;\n    minDeterminant 0.001;\n    minFaceWeight 0.02;\n    minVolRatio 0.01;\n    minTriangleTwist -1;\n\n\n\n\n    // Advanced\n\n    nSmoothScale 4;\n    errorReduction 0.75;\n};\n\n\n// ************************************************************************* //\n',
    'snappyHexMeshDict': '/*--------------------------------*- C++ -*----------------------------------*\\\n| =========                 |                                                 |\n| \\\\      /  F ield         | OpenFOAM: The Open Source CFD Toolbox           |\n|  \\\\    /   O peration     | Website:  www.openfoam.org                      |\n|   \\\\  /    A nd           | Version:  12                                    |\n|    \\\\/     M anipulation  |                                                 |\n\\*---------------------------------------------------------------------------*/\nFoamFile\n{\n    version     2.0;\n    format      ascii;\n    class       dictionary;\n    object      snappyHexMeshDict;\n}\n// * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * //\n\n// Which of the steps to run\ncastellatedMesh true;\nsnap            true;\naddLayers       false;\n\n\n// Geometry. Definition of all surfaces. All surfaces are of class\n// searchableSurface.\n// Surfaces are used\n// - to specify refinement for any mesh cell intersecting it\n// - to specify refinement for any mesh cell inside/outside/near\n// - to \'snap\' the mesh boundary to the surface\ngeometry\n{\n    join\n    {\n        file    "join.stl";\n        type    triSurfaceMesh;\n        regions\n        {\n            inlet     { name inlet;     }\n            outlet    { name outlet;    } \n            lowerWall { name lowerWall; }\n            upperWall { name upperWall; }\n            rightWall { name rightWall; }\n            front     { name front;     }\n            back      { name back;      }\n            axi       { name axi;       }\n        }\n    }\n};\n\n\n\n// Settings for the castellatedMesh generation.\ncastellatedMeshControls\n{\n\n    // Refinement parameters\n    // ~~~~~~~~~~~~~~~~~~~~~\n\n    // If local number of cells is >= maxLocalCells on any processor\n    // switches from from refinement followed by balancing\n    // (current method) to (weighted) balancing before refinement.\n    maxLocalCells 1000000;\n\n    // Overall cell limit (approximately). Refinement will stop immediately\n    // upon reaching this number so a refinement level might not complete.\n    // Note that this is the number of cells before removing the part which\n    // is not \'visible\' from the keepPoint. The final number of cells might\n    // actually be a lot less.\n    maxGlobalCells 70000000;\n\n    // The surface refinement loop might spend lots of iterations refining just a\n    // few cells. This setting will cause refinement to stop if <= minimumRefine\n    // are selected for refinement. Note: it will at least do one iteration\n    // (unless the number of cells to refine is 0)\n    minRefinementCells 10;\n\n    // Allow a certain level of imbalance during refining\n    // (since balancing is quite expensive)\n    // Expressed as fraction of perfect balance (= overall number of cells /\n    // nProcs). 0=balance always.\n    maxLoadUnbalance 0.10;\n\n\n    // Number of buffer layers between different levels.\n    // 1 means normal 2:1 refinement restriction, larger means slower\n    // refinement.\n    nCellsBetweenLevels 3;\n\n\n\n    // Explicit feature edge refinement\n    // ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~\n\n    // Specifies a level for any cell intersected by its edges.\n    // This is a featureEdgeMesh, read from constant/triSurface for now.\n    features\n    (\n        {\n            file "join.eMesh";\n            level 0;\n        }\n    );\n\n\n\n    // Surface based refinement\n    // ~~~~~~~~~~~~~~~~~~~~~~~~\n\n    // Specifies two levels for every surface. The first is the minimum level,\n    // every cell intersecting a surface gets refined up to the minimum level.\n    // The second level is the maximum level. Cells that \'see\' multiple\n    // intersections where the intersections make an\n    // angle > resolveFeatureAngle get refined up to the maximum level.\n\n    refinementSurfaces\n    {\n        join\n        {\n            level (0 0);\n            regions\n            {\n                inlet     { level (0 0); patchInfo { type patch; }} \n                outlet    { level (0 0); patchInfo { type patch; }} \n                lowerWall { level (0 0); patchInfo { type wall; }} \n                upperWall { level (0 0); patchInfo { type wall; }} \n                rightWall { level (0 0); patchInfo { type wall; }} \n                leftWall  { level (0 0); patchInfo { type wall; }} \n                front     { level (0 0); patchInfo { type patch; }} \n                back      { level (0 0); patchInfo { type patch; }} \n                axi       { level (0 0); patchInfo { type patch; }} \n\n            }\n        } \n    }\n\n    // Resolve sharp angles\n    resolveFeatureAngle 55;\n\n\n    // Region-wise refinement\n    // ~~~~~~~~~~~~~~~~~~~~~~\n\n    // Specifies refinement level for cells in relation to a surface. One of\n    // three modes\n    // - distance. \'levels\' specifies per distance to the surface the\n    //   wanted refinement level. The distances need to be specified in\n    //   descending order.\n    // - inside. \'levels\' is only one entry and only the level is used. All\n    //   cells inside the surface get refined up to the level. The surface\n    //   needs to be closed for this to be possible.\n    // - outside. Same but cells outside.\n\n    refinementRegions\n    {\n    }\n\n\n    // Mesh selection\n    // ~~~~~~~~~~~~~~\n\n    // After refinement patches get added for all refinementSurfaces and\n    // all cells intersecting the surfaces get put into these patches. The\n    // section reachable from the locationInMesh is kept.\n    // NOTE: This point should never be on a face, always inside a cell, even\n    // after refinement.\n    locationInMesh (0.14 0.13 0.001);\n\n\n    // Whether any faceZones (as specified in the refinementSurfaces)\n    // are only on the boundary of corresponding cellZones or also allow\n    // free-standing zone faces. Not used if there are no faceZones.\n    allowFreeStandingZoneFaces false;\n}\n\n\n\n// Settings for the snapping.\nsnapControls\n{\n    //- Number of patch smoothing iterations before finding correspondence\n    //  to surface\n    nSmoothPatch 3;\n\n    //- Relative distance for points to be attracted by surface feature point\n    //  or edge. True distance is this factor times local\n    //  maximum edge length.\n    tolerance 2.0;\n\n    //- Number of mesh displacement relaxation iterations.\n    nSolveIter 130;\n\n    //- Maximum number of snapping relaxation iterations. Should stop\n    //  before upon reaching a correct mesh.\n    nRelaxIter 5;\n\n    // Feature snapping\n\n        //- Number of feature edge snapping iterations.\n        //  Leave out altogether to disable.\n        nFeatureSnapIter 10;\n\n        //- Detect (geometric only) features by sampling the surface\n        //  (default=false).\n        implicitFeatureSnap false;\n\n        //- Use castellatedMeshControls::features (default = true)\n        explicitFeatureSnap true;\n\n        //- Detect points on multiple surfaces (only for explicitFeatureSnap)\n        multiRegionFeatureSnap false;\n}\n\n\n\n// Settings for the layer addition.\naddLayersControls\n{\n    // Are the thickness parameters below relative to the undistorted\n    // size of the refined cell outside layer (true) or absolute sizes (false).\n    relativeSizes true;\n\n    // Per final patch (so not geometry!) the layer information\n    layers\n    {\n    }\n\n    // Expansion factor for layer mesh\n    expansionRatio 1.0;\n\n    // Wanted thickness of final added cell layer. If multiple layers\n    // is the\n    // thickness of the layer furthest away from the wall.\n    // Relative to undistorted size of cell outside layer.\n    // is the thickness of the layer furthest away from the wall.\n    // See relativeSizes parameter.\n    finalLayerThickness 0.3;\n\n    // Minimum thickness of cell layer. If for any reason layer\n    // cannot be above minThickness do not add layer.\n    // Relative to undistorted size of cell outside layer.\n    minThickness 0.1;\n\n    // If points get not extruded do nGrow layers of connected faces that are\n    // also not grown. This helps convergence of the layer addition process\n    // close to features.\n    // Note: changed(corrected) w.r.t 17x! (didn\'t do anything in 17x)\n    nGrow 0;\n\n    // Advanced settings\n\n    // When not to extrude surface. 0 is flat surface, 90 is when two faces\n    // are perpendicular\n    featureAngle 60;\n\n    // At non-patched sides allow mesh to slip if extrusion direction makes\n    // angle larger than slipFeatureAngle.\n    slipFeatureAngle 30;\n\n    // Maximum number of snapping relaxation iterations. Should stop\n    // before upon reaching a correct mesh.\n    nRelaxIter 3;\n\n    // Number of smoothing iterations of surface normals\n    nSmoothSurfaceNormals 1;\n\n    // Number of smoothing iterations of interior mesh movement direction\n    nSmoothNormals 3;\n\n    // Smooth layer thickness over surface patches\n    nSmoothThickness 10;\n\n    // Stop layer growth on highly warped cells\n    maxFaceThicknessRatio 0.5;\n\n    // Reduce layer growth where ratio thickness to medial\n    // distance is large\n    maxThicknessToMedialRatio 0.3;\n\n    // Angle used to pick up medial axis points\n    // Note: changed(corrected) w.r.t 17x! 90 degrees corresponds to 130 in 17x.\n    minMedianAxisAngle 90;\n\n\n    // Create buffer region for new layer terminations\n    nBufferCellsNoExtrude 0;\n\n\n    // Overall max number of layer addition iterations. The mesher will exit\n    // if it reaches this number of iterations; possibly with an illegal\n    // mesh.\n    nLayerIter 50;\n}\n\n\n\n// Generic mesh quality settings. At any undoable phase these determine\n// where to undo.\nmeshQualityControls\n{\n    maxNonOrtho 65;\n    maxBoundarySkewness 20;\n    maxInternalSkewness 4;\n    maxConcave 80;\n    minFlatness 0.5;\n    minVol 1e-13;\n    minTetQuality 1e-9;\n    minArea -1;\n    minTwist 0.02;\n    minDeterminant 0.001;\n    minFaceWeight 0.02;\n    minVolRatio 0.01;\n    minTriangleTwist -1;\n\n\n\n    // Advanced\n\n\n    //- Number of error distribution iterations\n    nSmoothScale 4;\n    //- amount to scale back displacement at error points\n    errorReduction 0.75;\n}\n\n\n// Advanced\n\ndebug 0;\n\n\n// Write flags\nwriteFlags\n(\n    scalarLevels    // write volScalarField with cellLevel for postprocessing\n    layerSets       // write cellSets, faceSets of faces in layer\n    layerFields     // write volScalarField for layer coverage\n);\n\n\n// Merge tolerance. Is fraction of overall bounding box of initial mesh.\n// Note: the write tolerance needs to be higher than this.\nmergeTolerance 1e-6;\n\n\n// ************************************************************************* //\n',
    'surfaceFeaturesDict': '/*--------------------------------*- C++ -*----------------------------------*\\\n| =========                 |                                                 |\n| \\\\      /  F ield         | OpenFOAM: The Open Source CFD Toolbox           |\n|  \\\\    /   O peration     | Website:  www.openfoam.org                      |\n|   \\\\  /    A nd           | Version:  12                                    |\n|    \\\\/     M anipulation  |                                                 |\n\\*---------------------------------------------------------------------------*/\nFoamFile\n{\n    version     2.0;\n    format      ascii;\n    class       dictionary;\n    object      surfaceFeatureExtractDict;\n}\n// * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * //\n\ngeometric\n{\n    // The files of which you want to extract the features\n    // Located in constant/triSurface\n    surfaces\n    (\n        "join.stl"\n    );\n\n    //- Since 6.x\n    //  Needed especially for bad triangulations.\n    //  Always check your feature edge mesh\n    trimFeatures\n    {\n        //- Feature edges that contains less than \'minElem\' of edges are\n        //  removed automatically\n        minElem 1;\n\n        //- Remove feature edges that are less than the total length of [m]\n        minLen  0.001;\n    }\n\n    //- This is the angle between faces\n    includedAngle       120;\n\n    //- Since 6.x\n    //  Outputs the curvature of the surface\n    //curvature           no;\n\n    //- Since 6.x\n    //  Outputs the priximity of points and edges to each other\n    //featureProximity    no;\n\n    //- Since 6.x\n    //  The maximum search distance to use, when looking for other feature\n    //  points and edges\n    //maxFeatureProximity  1;\n\n    //- Write features for post processing into *.obj format\n    //  *.obj can be read by ParaView\n    writeObj            yes;\n\n    //- Write the surface proximity and curvature to the VTK format\n    writeVTK            no;\n}\n\n\n// ************************************************************************* //\n',
}
